{
  "name": "苏黎世仪器数据采集控制组件",
  "name_en": "Zurich Instruments DAQ control shell",
  "manufacturer": "",
  "description": "一个非物理的软件控制组件，用于连接苏黎世仪器 DAQ/LabOne 服务器及相关实验仪器会话，提供节点树读写、订阅轮询、示波采集、AWG 配置、DIO 调试以及部分开关/电源控制功能，适用于实验自动化与调试。",
  "description_en": "A non-physical software control component for connecting to Zurich Instruments DAQ/LabOne servers and related instrument sessions. It supports node-tree read/write, subscription polling, scope acquisition, AWG configuration, DIO diagnostics, and some switch/power control for lab automation and debugging.",
  "tag_hints": [
    "Zurich Instruments",
    "LabOne DAQ server",
    "node tree access",
    "scope acquisition",
    "AWG configuration",
    "DIO calibration",
    "instrument session control"
  ],
  "actions": [
    {
      "action_name": "auto-connect_device",
      "description": "通过指定接口连接设备会话。",
      "description_en": "Connect to a device session through the specified interface."
    },
    {
      "action_name": "auto-connect_server",
      "description": "连接到 DAQ/LabOne 服务器。",
      "description_en": "Connect to the DAQ/LabOne server."
    },
    {
      "action_name": "auto-features",
      "description": "查询当前会话支持的功能或特性。",
      "description_en": "Query the features supported by the current session."
    },
    {
      "action_name": "auto-find",
      "description": "查找匹配条件的节点路径。",
      "description_en": "Find a node path matching the requested criteria."
    },
    {
      "action_name": "auto-finds",
      "description": "查找多个匹配条件的节点路径。",
      "description_en": "Find multiple node paths matching the requested criteria."
    },
    {
      "action_name": "auto-getd",
      "description": "读取指定节点的双精度数值。",
      "description_en": "Read a double-precision value from the specified node."
    },
    {
      "action_name": "auto-geti",
      "description": "读取指定节点的整数值。",
      "description_en": "Read an integer value from the specified node."
    },
    {
      "action_name": "auto-getv",
      "description": "读取指定节点的向量或数组数据。",
      "description_en": "Read vector or array data from the specified node."
    },
    {
      "action_name": "auto-load_settings",
      "description": "加载配置文件到当前服务器或设备会话。",
      "description_en": "Load a settings file into the current server or device session."
    },
    {
      "action_name": "auto-poll",
      "description": "轮询已订阅节点的数据。",
      "description_en": "Poll data from subscribed nodes."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接当前服务器或设备会话。",
      "description_en": "Reconnect the current server or device session."
    },
    {
      "action_name": "auto-setd",
      "description": "向指定节点写入双精度数值。",
      "description_en": "Write a double-precision value to the specified node."
    },
    {
      "action_name": "auto-seti",
      "description": "向指定节点写入整数值。",
      "description_en": "Write an integer value to the specified node."
    },
    {
      "action_name": "auto-setv",
      "description": "向指定节点写入向量或数组数据。",
      "description_en": "Write vector or array data to the specified node."
    },
    {
      "action_name": "auto-subs",
      "description": "订阅指定节点以进行后续数据轮询。",
      "description_en": "Subscribe to the specified node for later polling."
    },
    {
      "action_name": "auto-sync",
      "description": "同步与服务器之间的待处理操作。",
      "description_en": "Synchronize pending operations with the server."
    },
    {
      "action_name": "auto-unsubs",
      "description": "取消订阅指定节点。",
      "description_en": "Unsubscribe from the specified node."
    },
    {
      "action_name": "auto-idn",
      "description": "查询已连接仪器的身份标识信息。",
      "description_en": "Query the identification information of the connected instrument."
    },
    {
      "action_name": "auto-set_trigger_mode",
      "description": "设置示波采集的触发模式。",
      "description_en": "Set the trigger mode for scope acquisition."
    },
    {
      "action_name": "auto-set_trigger_level",
      "description": "设置触发电平。",
      "description_en": "Set the trigger level."
    },
    {
      "action_name": "auto-set_trigger_ext",
      "description": "配置外部触发输入。",
      "description_en": "Configure the external trigger input."
    },
    {
      "action_name": "auto-set_trigger_src",
      "description": "选择触发源。",
      "description_en": "Select the trigger source."
    },
    {
      "action_name": "auto-set_trigger_slope",
      "description": "设置触发边沿斜率。",
      "description_en": "Set the trigger edge slope."
    },
    {
      "action_name": "auto-set_trigger_coupling",
      "description": "设置触发耦合方式。",
      "description_en": "Set the trigger coupling mode."
    },
    {
      "action_name": "auto-set_time_scale",
      "description": "设置示波时间刻度。",
      "description_en": "Set the scope time scale."
    },
    {
      "action_name": "auto-set_channel_scale",
      "description": "设置通道幅度刻度。",
      "description_en": "Set the channel amplitude scale."
    },
    {
      "action_name": "auto-do_single_shot",
      "description": "执行一次单次采集。",
      "description_en": "Perform a single-shot acquisition."
    },
    {
      "action_name": "auto-set_averaging",
      "description": "设置或启用平均采样功能。",
      "description_en": "Configure or enable waveform averaging."
    },
    {
      "action_name": "auto-set_format_real",
      "description": "设置数据为实数格式输出。",
      "description_en": "Set the data output to real-number format."
    },
    {
      "action_name": "auto-set_average_count",
      "description": "设置平均次数。",
      "description_en": "Set the averaging count."
    },
    {
      "action_name": "auto-do_get_screenshot",
      "description": "获取当前示波界面的截图。",
      "description_en": "Capture a screenshot of the current scope display."
    },
    {
      "action_name": "auto-get_channel_data",
      "description": "读取指定通道的波形数据。",
      "description_en": "Read waveform data from the specified channel."
    },
    {
      "action_name": "auto-is_averaging_complete",
      "description": "检查平均采集是否完成。",
      "description_en": "Check whether averaging acquisition is complete."
    },
    {
      "action_name": "auto-set_maximum_rate",
      "description": "设置最大采样或采集速率。",
      "description_en": "Set the maximum sampling or acquisition rate."
    },
    {
      "action_name": "auto-configure_awg_file",
      "description": "从文件配置 AWG 程序或参数。",
      "description_en": "Configure the AWG program or settings from a file."
    },
    {
      "action_name": "auto-configure_awg_string",
      "description": "从文本字符串配置 AWG 程序或参数。",
      "description_en": "Configure the AWG program or settings from a text string."
    },
    {
      "action_name": "auto-read_scope",
      "description": "读取连接设备的示波数据。",
      "description_en": "Read scope data from the connected device."
    },
    {
      "action_name": "auto-restart",
      "description": "重启当前连接的模块、设备或开关单元。",
      "description_en": "Restart the currently connected module, device, or switch unit."
    },
    {
      "action_name": "auto-on",
      "description": "向目标通道、输出或开关发送开启命令。",
      "description_en": "Send an ON command to the target channel, output, or switch."
    },
    {
      "action_name": "auto-off",
      "description": "向目标通道、输出或开关发送关闭命令。",
      "description_en": "Send an OFF command to the target channel, output, or switch."
    },
    {
      "action_name": "auto-extclk",
      "description": "切换或设置为外部时钟参考。",
      "description_en": "Switch to or configure an external clock reference."
    },
    {
      "action_name": "auto-sampleclk",
      "description": "设置采样时钟参数。",
      "description_en": "Configure the sampling clock."
    },
    {
      "action_name": "auto-mode",
      "description": "设置设备或模块的工作模式。",
      "description_en": "Set the operating mode of the device or module."
    },
    {
      "action_name": "auto-direct",
      "description": "设置直通或直接控制模式。",
      "description_en": "Set direct or bypass control mode."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "校准 DIO 协议的时序或对齐。",
      "description_en": "Calibrate DIO protocol timing or alignment."
    },
    {
      "action_name": "auto-dio_snapshot",
      "description": "采集当前 DIO 状态快照。",
      "description_en": "Capture a snapshot of the current DIO state."
    },
    {
      "action_name": "auto-awg_dio_snapshot",
      "description": "采集 AWG 相关的 DIO 状态快照。",
      "description_en": "Capture a snapshot of the AWG-related DIO state."
    },
    {
      "action_name": "auto-dio_testmode",
      "description": "设置或启用 DIO 测试模式。",
      "description_en": "Configure or enable DIO test mode."
    },
    {
      "action_name": "auto-onOffMultiple",
      "description": "批量控制多个通道或开关的开关状态。",
      "description_en": "Switch multiple channels or outlets on or off in batch."
    }
  ]
}

